use serde_json::{Value, Map};

pub fn solve(input: Value) -> Value {
    let arr = input.as_array().unwrap();
    let mut left_map: Map<i64, i64> = Map::new();
    let mut right_map: Map<i64, i64> = Map::new();

    for row in arr[0].as_array().unwrap() {
        let key = row[0].as_i64().unwrap();
        let value = row[1].as_i64().unwrap();
        left_map.insert(key, value);
    }

    for row in arr[1].as_array().unwrap() {
        let key = row[0].as_i64().unwrap();
        let value = row[1].as_i64().unwrap();
        right_map.insert(key, value);
    }

    let mut result: Vec<Value> = Vec::new();
    for key in left_map.keys().chain(right_map.keys()).cloned().collect::<Vec<_>>() {
        if let Some(left_value) = left_map.get(&key) {
            if let Some(right_value) = right_map.get(&key) {
                result.push(Value::Array(vec![Value::Number(key.into()), Value::Number(*left_value), Value::Number(*right_value)]));
            }
        }
    }

    result.sort_by_key(|v| v[0].as_i64().unwrap());
    Value::Array(result)
}
